#include QMK_KEYBOARD_H

enum Layer {
    L_Numpad = 0,
    L_Symbols,
    L_RGB,
};

// clang-format off
const uint16_t PROGMEM keymaps[][MATRIX_ROWS][MATRIX_COLS] = {
  /*
   * Macropad Button Order
   * ┌───┬───┬───┬───┐
   * │ 7 │ 8 │ 9 │ - │
   * ├───┼───┼───┼───┤
   * │ 4 │ 5 │ 6 │ + │
   * ├───┼───┼───┼───┤
   * │ 1 │ 2 │ 3 │ 0 │
   * └───┴───┴───┴───┘
   *
   * SNES Button Order
   * ┌────────┬────────┬────────┬────────┐
   * │   LT   │   RT   │ START  │ SELECT │
   * ├────────┼────────┼────────┼────────┤
   * │   UP   │  DOWN  │  LEFT  │ RIGHT  │
   * ├────────┼────────┼────────┼────────┤
   * │   A    │   B    │   X    │   Y    │
   * └────────┴────────┴────────┴────────┘
   *
   */
  [L_Numpad] = LAYOUT(
      KC_P7,   KC_P8,   KC_P9,   TO(L_RGB)
    , KC_P4,   KC_P5,   KC_P6,   LT(L_Symbols, KC_PCMM)
    , KC_P1,   KC_P2,   KC_P3,   KC_P0

    , KC_A,    KC_S,    KC_ENT,  KC_BSPC
    , KC_UP,   KC_DOWN, KC_LEFT, KC_RIGHT
    , KC_X,    KC_Z,    LSFT(KC_F1),KC_TAB
  ),
  [L_RGB] = LAYOUT(
      RGB_M_P,  RGB_M_B, UG_TOGG, KC_NO
    , UG_NEXT,  UG_HUEU, UG_VALU, TO(L_Numpad)
    , UG_PREV,  UG_HUED, UG_VALD, KC_NO

    , KC_A,    KC_B,    KC_C,    KC_D
    , KC_E,    KC_F,    KC_G,    KC_H
    , KC_I,    KC_J,    KC_K,    KC_L
  ),
  [L_Symbols] = LAYOUT(
      KC_PPLS, KC_PMNS, KC_PEQL, KC_NO
    , KC_PAST, KC_PSLS, KC_ENT,  KC_TRNS
    , KC_NUM,  KC_NO,   KC_NO,   QK_BOOT

    , KC_A,    KC_B,    KC_C,    KC_D
    , KC_E,    KC_F,    KC_G,    KC_H
    , KC_I,    KC_J,    KC_K,    KC_L
  )
};
// clang-format on

const char* get_layer_name_user(uint8_t layer) {
    switch (layer) {
        case L_Numpad:
            return "Numpad";
        case L_RGB:
            return "RGB Controls";
        case L_Symbols:
            return "Symbols";
        default:
            return "Undef";
    }
}
